import { createHash } from "node:crypto";
import {
  existsSync,
  readFileSync,
  readdirSync,
  mkdirSync,
  writeFileSync,
  renameSync,
  rmSync,
  lstatSync,
} from "node:fs";
import path from "node:path";

const idPattern = /^[a-z0-9][a-z0-9-]{0,79}$/u;
const marker =
  "// Generated by Design Lab. Edit designs/, then run pnpm sync.\n";
export function discover(root) {
  const directory = path.join(root, "designs");
  if (!existsSync(directory)) return [];
  const files = [];
  for (const entry of readdirSync(directory, { withFileTypes: true }).sort(
    (a, b) => a.name.localeCompare(b.name)
  )) {
    if (!entry.isDirectory() || entry.name.startsWith(".")) continue;
    const id = entry.name;
    if (!idPattern.test(id))
      throw new Error(
        `Invalid design folder: ${id}. Use lowercase letters, digits, and hyphens.`
      );
    const base = path.join(directory, id);
    const manifestPath = path.join(base, "design.json");
    if (!existsSync(manifestPath)) continue;
    const manifest = JSON.parse(readFileSync(manifestPath, "utf8"));
    if (
      !manifest ||
      typeof manifest !== "object" ||
      typeof manifest.title !== "string" ||
      !manifest.title.trim()
    )
      throw new Error(`${id}/design.json requires a title.`);
    const kind = manifest.kind ?? "web";
    if (!["web", "email"].includes(kind))
      throw new Error(`${id}: kind must be web or email.`);
    const width = manifest.width ?? (kind === "email" ? 640 : 1440);
    if (!Number.isInteger(width) || width < 240 || width > 7680)
      throw new Error(`${id}: width must be 240–7680.`);
    const versionsDir = path.join(base, "versions");
    if (!existsSync(versionsDir))
      throw new Error(
        `${id}: add versions/v1.tsx with a default component export.`
      );
    const versions = readdirSync(versionsDir)
      .filter((name) => name.endsWith(".tsx"))
      .map((name) => name.slice(0, -4))
      .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
    if (!versions.length)
      throw new Error(`${id}: add at least one .tsx version.`);
    for (const version of versions) {
      if (
        !idPattern.test(version) ||
        lstatSync(path.join(versionsDir, `${version}.tsx`)).isSymbolicLink()
      )
        throw new Error(`${id}: invalid version ${version}.`);
    }
    if (manifest.result !== undefined && !versions.includes(manifest.result))
      throw new Error(`${id}: result must name an existing version.`);
    if (
      manifest.resultStatus !== undefined &&
      !["wip", "approved"].includes(manifest.resultStatus)
    )
      throw new Error(`${id}: invalid resultStatus.`);
    const pages = manifest.pages ?? [
      { id: "concepts", title: "Concepts", versions },
    ];
    if (!Array.isArray(pages) || !pages.length)
      throw new Error(`${id}: pages must be a nonempty array.`);
    const pageIds = new Set();
    const used = new Set();
    const resultPages = pages.map((page) => {
      if (
        !page ||
        !idPattern.test(page.id) ||
        pageIds.has(page.id) ||
        typeof page.title !== "string" ||
        !Array.isArray(page.versions) ||
        !page.versions.length
      )
        throw new Error(`${id}: invalid or duplicate page.`);
      pageIds.add(page.id);
      return {
        id: page.id,
        title: page.title,
        boards: page.versions.map((version) => {
          if (!versions.includes(version) || used.has(version))
            throw new Error(`${id}: unknown or repeated version ${version}.`);
          used.add(version);
          return {
            id: `${id}-${version}`,
            title: version.toUpperCase(),
            description: page.title,
            width,
            height: kind === "email" ? 900 : 1000,
            preview: `/previews/generated/${id}/${version}`,
            sourcePath: `designs/${id}/versions/${version}.tsx`,
            exportUrl:
              kind === "email" ? `/api/exports/${id}/${version}` : undefined,
          };
        }),
      };
    });
    const missing = versions.filter((v) => !used.has(v));
    if (missing.length)
      throw new Error(
        `${id}: add ${missing.join(", ")} to pages or remove the pages setting for automatic discovery.`
      );
    // Shared components and assets can change a version without its entry file changing.
    const revision = fingerprint(base);
    for (const page of resultPages)
      for (const board of page.boards) board.preview += `?revision=${revision}`;
    files.push({
      id,
      title: manifest.title,
      href: `/files/${id}`,
      kind,
      pages: resultPages,
      versions,
      result: manifest.result,
      ...(manifest.result
        ? {
            final: {
              label: manifest.result,
              ...(manifest.resultStatus === "approved"
                ? {}
                : { status: "wip" }),
            },
          }
        : {}),
    });
  }
  return files;
}
function fingerprint(directory) {
  const hash = createHash("sha256");
  function walk(dir) {
    for (const entry of readdirSync(dir, { withFileTypes: true }).sort((a, b) =>
      a.name.localeCompare(b.name)
    )) {
      const p = path.join(dir, entry.name);
      if (entry.isDirectory()) walk(p);
      else if (entry.isFile()) {
        hash.update(path.relative(directory, p));
        hash.update(readFileSync(p));
      }
    }
  }
  walk(directory);
  return hash.digest("hex").slice(0, 12);
}
function writeChanged(file, text) {
  if (existsSync(file) && readFileSync(file, "utf8") === text) return;
  mkdirSync(path.dirname(file), { recursive: true });
  const temp = `${file}.${process.pid}.tmp`;
  writeFileSync(temp, text);
  renameSync(temp, file);
}
export function syncWorkspace(root = process.cwd()) {
  const files = discover(root);
  const outputs = new Map();
  for (const file of files)
    for (const version of file.versions) {
      const source = `designs/${file.id}/versions/${version}`;
      const preview = `app/previews/generated/${file.id}/${version}/${file.kind === "email" ? "route.ts" : "page.tsx"}`;
      const relative = path
        .relative(path.dirname(preview), source)
        .split(path.sep)
        .join("/");
      const template = `import Design from ${JSON.stringify(relative)};\n`;
      if (file.kind === "email") {
        const renderer = `import { createElement } from 'react';\nimport { render, toPlainText } from '@react-email/components';\n`;
        outputs.set(
          preview,
          marker +
            template +
            renderer +
            `export async function GET() { const html = await render(createElement(Design)); return new Response(html, { headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store', 'Content-Security-Policy': "script-src 'none'" } }); }\n`
        );
        const route = `app/api/exports/${file.id}/${version}/route.ts`;
        const ref = path
          .relative(path.dirname(route), source)
          .split(path.sep)
          .join("/");
        outputs.set(
          route,
          marker +
            `import Design from ${JSON.stringify(ref)};\n` +
            renderer +
            `export async function GET(request: Request) { const html = await render(createElement(Design)); const plain = new URL(request.url).searchParams.get('format') === 'text'; return new Response(plain ? toPlainText(html) : html, { headers: { 'Content-Type': plain ? 'text/plain; charset=utf-8' : 'text/html; charset=utf-8', 'Content-Disposition': 'attachment; filename="${file.id}-${version}.' + (plain ? 'txt' : 'html') + '"', 'Cache-Control': 'no-store' } }); }\n`
        );
      } else
        outputs.set(
          preview,
          marker +
            template +
            `export default function Preview() { return <div data-design-source=${JSON.stringify(`${source}.tsx`)} style={{ display: "contents" }}><Design /></div>; }\n`
        );
    }
  const indexPath = path.join(root, ".studio/generated-routes.json");
  const previous = existsSync(indexPath)
    ? JSON.parse(readFileSync(indexPath, "utf8"))
    : [];
  // Validate every target before writing or removing anything.
  for (const relative of outputs.keys()) {
    const full = path.join(root, relative);
    if (existsSync(full) && !readFileSync(full, "utf8").startsWith(marker))
      throw new Error(`Refusing to overwrite authored route: ${relative}`);
  }
  for (const old of previous) {
    if (
      typeof old !== "string" ||
      !/^app\/(previews\/generated|api\/exports)\/[a-z0-9-]+\/[a-z0-9-]+\/(page\.tsx|route\.ts)$/u.test(
        old
      )
    )
      throw new Error("Invalid generated route index.");
    if (!outputs.has(old)) {
      const full = path.join(root, old);
      if (existsSync(full) && readFileSync(full, "utf8").startsWith(marker))
        rmSync(full);
    }
  }
  for (const [relative, source] of outputs)
    writeChanged(path.join(root, relative), source);
  writeChanged(
    path.join(root, ".studio/catalog.ts"),
    marker +
      `import type { StudioFile } from '@la-agent/design-lab/types';\nexport const files: StudioFile[] = ${JSON.stringify(files, null, 2)};\n`
  );
  writeChanged(indexPath, JSON.stringify([...outputs.keys()], null, 2) + "\n");
  return files;
}
